import * as seed from './data.js';
let d={...seed};
import {assessments,alertsFor,supplierMatches,today} from './risk.js';
import {service} from './services.js';
const app=document.querySelector('#app');
const navOps=[['dashboard','◫','Dashboard'],['scan','▧','Scan medicine'],['inventory','▤','Inventory'],['risks','◉','Risk Radar'],['shipments','⇢','Shipments'],['trace','⌁','Batch traceability'],['suppliers','♧','Suppliers'],['alerts','⚑','Alerts'],['analytics','▥','Analytics'],['settings','⚙','Settings']];
const navPatient=[['home','⌂','Home'],['scan','▧','Find a medicine'],['medicines','▤','Medicines'],['refill','↻','Refill plans'],['reminders','◷','Reminders']];
let state={apiConnected:null,apiError:'',finderMatches:null,notificationPreferences:{inApp:true,caregiverOptIn:false},role:'Inventory Manager',page:'dashboard',selected:null,scanResult:null,scanMessage:'',recentScans:[],cameraStream:null,filter:'All',query:'',alerts:{},alertOwners:{},lastAlertChange:null,notice:'',modal:null,contrast:false,reduced:false,font:18,weights:{...d.factorsConfig.weights},thresholds:{...d.factorsConfig.thresholds},supplierReq:{quantity:1000,days:2,distance:25,reliability:70},flagged:[],plan:{...d.patientPlan},refillStep:1,roleScreen:true};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const activeRole=()=>['Patient','Caregiver'].includes(state.role)?'patient':'ops';
const allRisks=()=>assessments({weights:state.weights,thresholds:state.thresholds});
const riskFor=id=>allRisks().find(r=>r.medicineId===id);
const med=id=>d.medicines.find(m=>m.id===id);
const batch=id=>d.batches.find(b=>b.id===id);
const location=id=>d.locations.find(l=>l.id===id)?.name||'—';
const supplier=id=>d.suppliers.find(s=>s.id===id);
const alertList=()=>alertsFor({weights:state.weights,thresholds:state.thresholds}).map(a=>({...a,status:state.alerts[a.id]||a.status}));
let supplierMatchRequest=0;
async function refreshSupplierMatches(focusKey=null){const token=++supplierMatchRequest,medicineId=state.selected||'med-amox';try{const results=await service.findAlternatives(med(medicineId).name,state.supplierReq);if(token===supplierMatchRequest&&state.modal==='finder') {state.finderMatches={medicineId,results};render();if(focusKey)document.querySelector(`.req-input[data-key="${focusKey}"]`)?.focus();}}catch(error){state.notice=`Supplier matches are unavailable: ${error.message}`;render();}}
const stockGap=(m,r)=>{const next=d.shipments.filter(s=>s.medicineId===m.id&&s.status!=='Delivered').sort((a,b)=>a.eta.localeCompare(b.eta))[0];if(!next)return '';const arrival=Math.max(0,Math.ceil((new Date(`${next.eta}T00:00:00`)-today)/86400000));const gap=Math.max(0,arrival-r.stockout);return gap?` If ${next.id} arrives as estimated, the stock gap could be about ${gap} days (${Math.ceil(gap*m.daily)} ${m.unit}).`:` The next shipment is expected before the current stock estimate runs out.`};
const badge=(text,kind='neutral')=>`<span class="badge ${kind}">${esc(text)}</span>`;
const kindFor=x=>({Low:'good',Moderate:'moderate',High:'high',Critical:'critical',Open:'high',Acknowledged:'moderate',Resolved:'good',Delayed:'high',Delivered:'good',Active:'good',Review:'moderate','At risk':'high','In transit':'moderate'}[x]||'neutral');
const riskBadge=x=>badge(`${x.level} risk · ${x.score}`,kindFor(x.level));
function header(title,sub,actions=''){return `<div class="page-head"><div><p class="eyebrow">MEDISYNC · DEMO DATA</p><h1>${title}</h1><p class="lede">${sub}</p></div><div class="head-actions">${actions}</div></div>`}
function button(text,action,cls='secondary',attrs=''){return `<button class="btn ${cls}" data-action="${action}" ${attrs}>${text}</button>`}
function card(title,body,extra=''){return `<section class="card ${extra}"><h2>${title}</h2>${body}</section>`}
function table(headers,rows,empty='No records match these filters.'){return rows.length?`<div class="table-scroll" tabindex="0" aria-label="Scrollable data table"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:`<div class="empty"><b>Nothing to show yet</b><span>${empty}</span></div>`}
function metric(label,value,detail,icon='•'){return `<article class="metric"><span class="metric-icon" aria-hidden="true">${icon}</span><div><p>${label}</p><strong>${value}</strong><small>${detail}</small></div></article>`}
function access(){return `<main class="access"><div class="access-brand"><div class="brand-mark">✚</div><span>Medisync</span><span class="demo-pill">DEMO MODE</span></div><div class="access-grid"><div class="access-copy"><p class="eyebrow">MEDICINE SUPPLY, MADE CLEARER</p><h1>From medicine stock to a safer next step.</h1><p>One clear view for inventory teams, supply partners, patients, and caregivers.</p><div class="access-points"><div>✓ <span>Understand stock and shipment risks</span></div><div>✓ <span>See where each batch has travelled</span></div><div>✓ <span>Plan refills with consent and approval</span></div></div></div><section class="access-panel"><div class="demo-tag">DEMO MODE · SAMPLE RECORDS</div><h2>Choose your demo view</h2><p>This demo does not use real sign-in or connect to live inventory.</p><label for="role-choice">I’m viewing as</label><select id="role-choice" class="control"><option>Inventory Manager</option><option>Procurement Staff</option><option>Patient</option><option>Caregiver</option><option>Administrator</option></select>${button('Enter demo workspace','enter','primary wide')}<p class="access-foot">${state.apiConnected===false?`Local service is unavailable (${esc(state.apiError)}). Start Medisync with npm start.`:state.apiConnected?'Connected to the local demo service. Your sample actions are saved on this device.':'No account, personal data, or real medicine orders are used.'}</p></section></div><div class="access-bottom">Clear information for the whole care network <span>Accessible by default · Demo environment</span></div></main>`}
function shell(){const patient=activeRole()==='patient',nav=patient?navPatient:navOps;return `<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">✚</div><span>Medisync</span></div><div class="workspace-label">${patient?'PERSONAL CARE':'SUPPLY OPERATIONS'}</div><nav aria-label="Main navigation">${nav.map(([id,icon,label])=>`<button class="nav-item ${state.page===id?'active':''}" data-page="${id}" aria-current="${state.page===id?'page':'false'}"><span class="nav-icon" aria-hidden="true">${icon}</span><span>${label}</span>${id==='alerts'?`<small>${alertList().filter(a=>a.status==='Open').length}</small>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note"><b>DEMO DATA</b><span>Sample records and simulated actions</span></div><button class="nav-item" data-action="role-switch"><span class="nav-icon">⇄</span><span>Change demo role</span></button><div class="user-chip"><div class="avatar">${state.role[0]}</div><div><b>${esc(state.role)}</b><small>Demo workspace</small></div></div></div></aside><div class="main-wrap"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Toggle navigation">☰</button><div class="breadcrumb">Workspace <span>/</span> <b>${(patient?navPatient:navOps).find(n=>n[0]===state.page)?.[2]||state.page}</b></div><div class="top-actions"><span class="demo-pill">${state.apiConnected===false?'DEMO MODE · OFFLINE':state.apiConnected?'DEMO MODE · SAVED LOCALLY':'DEMO MODE'}</span><button class="icon-button" data-action="text-size" aria-label="Change text size">A<sup>+</sup></button><button class="icon-button ${state.contrast?'selected':''}" data-action="contrast" aria-label="Toggle high contrast">◐</button><button class="icon-button ${state.reduced?'selected':''}" data-action="motion" aria-label="Toggle reduced motion">◌</button></div></header><main id="main" class="content">${pageView()}</main><footer>Medisync · Demo data only <span>Sample records · No live orders or message delivery</span></footer></div></div>${state.notice?`<div class="toast" role="status">✓ ${esc(state.notice)} ${state.lastAlertChange?`<button data-action="undo-alert">Undo</button>`:''}<button data-action="dismiss-toast" aria-label="Dismiss">×</button></div>`:''}${state.modal?modalView():''}`}
function dashboard(){const rs=allRisks(),al=alertList(),urgent=rs.filter(r=>['High','Critical'].includes(r.level)).sort((a,b)=>b.score-a.score),focus=urgent[0];
return `${header('Today’s priority','One clear signal. One safe next step.')}<section class="focus-hero"><div class="focus-copy"><div class="focus-kicker"><span class="pulse-mark">!</span> NEEDS ATTENTION <span class="demo-tag">DEMO DATA</span></div><h2>${focus?`${focus.medicine.name.split(' ')[0]} may run out soon`:'Your medicine supply is looking steady'}</h2><p class="focus-message">${focus?`About ${focus.stockout} days of stock left. Its delivery is ${focus.delay} days late.`:'No high-risk medicine is flagged in the current demo records.'}</p><div class="focus-actions">${focus?button('Find backup supply','finder','primary',`data-med="${focus.medicineId}"`):button('Open inventory','clear-filters','primary')}${focus?button('Why this alert?','open-risk','quiet',`data-id="${focus.medicineId}"`):''}</div><div class="focus-safe">Demo records only. No order will be placed.</div></div><div class="focus-visual" aria-label="About ${focus?.stockout||30} days of stock remaining"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="focus-center"><span>STOCK LEFT</span><b>${focus?.stockout||30}<small>days</small></b><span>estimated</span></div><div class="floating-note"><span class="alert-dot high"></span> Delivery late</div></div></section><div class="dashboard-shortcuts"><button data-page="scan"><span>▧</span><b>Scan a medicine</b><small>Barcode or name</small><i>→</i></button><button data-page="shipments"><span>⇢</span><b>Track delivery</b><small>Shipment status</small><i>→</i></button><button data-page="alerts"><span>⚑</span><b>Review alerts</b><small>${al.filter(a=>a.status==='Open').length} need attention</small><i>→</i></button></div><p class="dashboard-footnote">More details live in Inventory, Risk Radar, Shipments, and Alerts.</p>`}
function inventoryPage(){let rows=d.batches.filter(b=>{const m=med(b.medicineId),r=riskFor(m.id),s=supplier(b.supplierId),q=state.query.toLowerCase();return(!q||`${m.name} ${m.generic} ${b.id} ${s?.name} ${location(b.locationId)}`.toLowerCase().includes(q))&&(state.filter==='All'||state.filter==='Low stock'&&r.pct<=m.threshold||state.filter==='High risk'&&['High','Critical'].includes(r.level)||state.filter==='Near expiry'&&((new Date(b.expiry)-today)/86400000<=30)||state.filter===b.status)}).map(b=>{let m=med(b.medicineId),r=riskFor(m.id),remaining=Math.ceil(b.quantity/m.daily);return `<tr><td><button class="table-link" data-open-med="${m.id}">${m.name}</button><small>${m.generic}</small></td><td><button class="table-link" data-trace="${b.id}">${b.id}</button></td><td><b>${b.quantity.toLocaleString()}</b> ${m.unit}<small>${r.pct}% stock cover · ${remaining} days in batch</small></td><td>${b.expiry}<small>${Math.max(0,Math.ceil((new Date(b.expiry)-today)/86400000))} days left</small></td><td><button class="table-link" data-supplier="${b.supplierId}">${supplier(b.supplierId)?.name||'—'}</button></td><td>${location(b.locationId)}</td><td>${riskBadge(r)}</td><td>${badge(b.status,kindFor(b.status))}</td></tr>`});
return `${header('Inventory','Search and filter batches across your demo locations.',button('Export sample CSV','export','secondary'))}<div class="filter-bar"><label class="search-control"><span aria-hidden="true">⌕</span><input id="search" class="control" type="search" placeholder="Search medicine, batch, supplier…" value="${esc(state.query)}" aria-label="Search inventory"></label><label class="filter-label">Show<select id="filter" class="control"><option ${state.filter==='All'?'selected':''}>All</option><option ${state.filter==='Low stock'?'selected':''}>Low stock</option><option ${state.filter==='Near expiry'?'selected':''}>Near expiry</option><option ${state.filter==='High risk'?'selected':''}>High risk</option><option>Available</option><option>Cold storage</option></select></label>${button('Clear filters','clear-filters','quiet')}</div><div class="card data-card"><div class="table-meta"><b>${rows.length} batch records</b><span>Demo data · updated for this presentation</span></div>${table(['Medicine / generic','Batch','Quantity / stock cover','Expiry','Supplier','Location','Calculated risk','Status'],rows)}</div>`}
function risksPage(){const rs=allRisks().sort((a,b)=>b.score-a.score);return `${header('Risk Radar','A transparent demo score from stock, delivery, supplier, expiry, and movement records.',button('How risk is calculated','risk-method','quiet'))}<div class="callout"><div class="callout-icon">◉</div><div><b>Risk score uses current demo records</b><p>Weighted model: stockout 30% · shipment delay 20% · supplier reliability 15% · expiry 15% · unusual movement 20%. Change weights in Settings.</p></div></div><div class="risk-grid">${rs.map(r=>`<article class="card risk-card"><div class="risk-card-head"><div><p class="eyebrow">RISK RADAR</p><h2>${r.medicine.name}</h2></div>${riskBadge(r)}</div><div class="risk-stats"><div><small>STOCK COVER</small><b>${r.pct}%</b></div><div><small>AT CURRENT USE</small><b>${r.stockout} days</b></div><div><small>NEAREST EXPIRY</small><b>${Math.max(0,r.daysToExpiry)} days</b></div></div><div class="factor-list">${r.factors.map(f=>`<div class="factor"><span>${f.label}</span><span>${f.detail}</span><b>+${f.contribution}</b></div>`).join('')}</div><div class="risk-action"><b>Recommended next step</b><p>${r.action}</p></div><div class="button-row">${button('See explanation','open-risk','secondary',`data-id="${r.medicineId}"`)}${(r.level==='High'||r.level==='Critical')?button('Find alternative suppliers','finder','primary',`data-med="${r.medicineId}"`):''}</div></article>`).join('')}</div>`}
function shipmentsPage(){const rows=d.shipments.map(s=>`<tr><td><button class="table-link" data-open-med="${s.medicineId}">${med(s.medicineId).name}</button><small><button class="table-link" data-trace="${s.batchId}">${s.batchId}</button></small></td><td>${s.id}<small><button class="table-link" data-supplier="${s.supplierId}">${s.carrier}</button></small></td><td>${s.quantity.toLocaleString()}</td><td>${s.origin}<small>to ${s.destination}</small></td><td>${s.eta}</td><td>${s.delay?`${s.delay} days late`:'On schedule'}</td><td>${badge(s.status,kindFor(s.status))}</td></tr>`);return `${header('Shipments','See what is moving, where it is headed, and whether the expected arrival has changed.')}<div class="metric-grid">${metric('Active',d.shipments.filter(s=>s.status!=='Delivered').length,'In transit or pending','⇢')}${metric('Delayed',d.shipments.filter(s=>s.delay>0).length,'Needs a delivery review','!')}${metric('Delivered',d.shipments.filter(s=>s.status==='Delivered').length,'Demo shipment records','✓')}</div><div class="card data-card">${table(['Medicine / batch','Shipment / supplier','Quantity','Route','Expected arrival','Delay','Status'],rows)}</div>`}
function tracePage(){const selected=batch(state.selected)||d.batches[0],m=med(selected.medicineId),events=d.traceEvents.filter(e=>e.batchId===selected.id);return `${header('Batch traceability','Review the recorded path for each sample batch. Scan events below are simulated demo records.',`<label class="filter-label">Batch<select id="trace-batch" class="control">${d.batches.map(b=>`<option value="${b.id}" ${b.id===selected.id?'selected':''}>${b.id} · ${med(b.medicineId).name}</option>`).join('')}</select></label>`)}<div class="trace-overview card"><div class="batch-stamp"><span>BATCH</span><b>${selected.id}</b><span>${m.name}</span></div><div class="trace-facts"><div><small>MANUFACTURER</small><b>${selected.manufacturer}</b></div><div><small>EXPIRY DATE</small><b>${selected.expiry}</b></div><div><small>QUANTITY AT LOCATION</small><b>${selected.quantity.toLocaleString()} ${m.unit}</b></div><div><small>CURRENT LOCATION</small><b>${location(selected.locationId)}</b></div></div></div>${card('Recorded journey',events.length?`<ol class="timeline">${events.map((e,i)=>`<li><div class="timeline-dot">${i+1}</div><div class="timeline-event"><div class="timeline-top"><b>${e.status}</b><span>${e.time}</span></div><p>${e.organization} · ${e.location}</p><div class="timeline-meta"><span>Batch ${e.batchId}</span><span>${e.quantity.toLocaleString()} units</span><span>Ref ${e.ref}</span></div><small class="scan-label">✓ Recorded via scan (demo)</small></div></li>`).join('')}</ol>`:'<div class="empty">No trace events recorded for this demo batch.</div>')}${d.inventory.some(i=>i.batchId===selected.id&&i.unusual)?`<div class="callout danger"><b>Traceability anomaly — review required</b><p>A recorded movement needs investigation. An anomaly does not prove a medicine is counterfeit.</p></div>`:''}<div class="route-steps"><span>Manufacturer</span><i>→</i><span>Distributor</span><i>→</i><span>Hospital / Pharmacy</span></div>`}
function suppliersPage(){const rows=d.suppliers.map(s=>`<tr><td><button class="table-link" data-supplier="${s.id}">${s.name}</button><small>${s.location}</small></td><td>${s.reliability}%</td><td>${s.medicines.join(', ')}</td><td>${s.units.toLocaleString()} units</td><td>${s.delivery} days</td><td>${s.delayed} delayed</td><td>${badge(s.status,kindFor(s.status))}</td></tr>`);return `${header('Suppliers','Compare demo suppliers, their availability, reliability, and delivery record.',button('Find alternatives','finder','primary'))}<div class="card data-card">${table(['Supplier / location','Reliability','Medicines supplied','Demo available stock','Avg. delivery','Delayed shipments','Status'],rows)}</div>`}
function alertsPage(){const al=alertList();return `${header('Alert center','Alerts are generated from demo records. Assign one to make the next step clear.')}<div class="filter-bar"><label class="filter-label">Status<select id="alert-filter" class="control"><option>All</option><option>Open</option><option>Acknowledged</option><option>Resolved</option></select></label><span class="quiet-text">${al.filter(a=>a.status==='Open').length} open alerts</span></div><div class="alert-list">${al.filter(a=>state.filter==='All'||a.status===state.filter).map(a=>`<article class="card alert-card"><div class="alert-severity ${kindFor(a.severity)}">${a.severity}</div><div class="alert-body"><div class="alert-title-row"><div><p class="eyebrow">${esc(a.title)}</p><h2>${med(a.medicineId)?.name||'Inventory record'}</h2></div>${badge(a.status,kindFor(a.status))}</div><p>${a.reason}</p><div class="alert-details"><span>Batch: ${a.batchId||'All batches'}</span><span>${a.time}</span><span>Owner: ${esc(state.alertOwners[a.id]||'Unassigned')}</span></div><div class="alert-recommend"><b>Recommended action</b><span>${a.action}</span></div><div class="button-row"><button class="btn quiet" data-alert-detail="${a.id}">View related record</button>${a.status==='Open'?button(state.alertOwners[a.id]===state.role?'Assigned to me':'Assign to me','assign-alert','secondary',`data-id="${a.id}"`):''}${a.status==='Open'?button('Acknowledge','ack','secondary',`data-id="${a.id}"`):a.status==='Acknowledged'?button('Resolve','resolve','secondary',`data-id="${a.id}"`):''}</div></div></article>`).join('')||'<section class="card empty">No alerts in this view.</section>'}</div>`}
function analyticsPage(){const rs=allRisks(),short=rs.filter(r=>r.stockout<=10).sort((a,b)=>a.stockout-b.stockout),expiring=d.batches.filter(b=>(new Date(b.expiry)-today)/86400000<=30),late=d.shipments.filter(s=>s.delay>0);return `${header('At a glance','Three questions to help decide what needs attention.',button('Download sample CSV','export','secondary'))}<p class="demo-tag analytics-demo-note">All figures use demo records</p><div class="analytics-simple-grid"><section class="card"><div class="analytics-question"><span>1</span><div><p class="eyebrow">STOCK</p><h2>What may run out soon?</h2></div></div>${short.length?short.slice(0,3).map(r=>`<button class="analytics-row" data-open-risk="${r.medicineId}"><b>${r.medicine.name}</b><span>${r.stockout} days left</span>${riskBadge(r)}</button>`).join(''):'<p>No near-term shortages in these demo records.</p>'}<button class="btn quiet" data-page="risks">See all supply risks →</button></section><section class="card"><div class="analytics-question"><span>2</span><div><p class="eyebrow">EXPIRY</p><h2>What expires in 30 days?</h2></div></div>${expiring.length?expiring.slice(0,3).map(b=>`<button class="analytics-row" data-trace="${b.id}"><b>${med(b.medicineId).name}</b><span>${b.quantity.toLocaleString()} ${med(b.medicineId).unit} · ${b.expiry}</span><span>Batch ${b.id}</span></button>`).join(''):'<p>No batches expire in the next 30 days.</p>'}<button class="btn quiet" data-page="inventory">Review inventory →</button></section><section class="card"><div class="analytics-question"><span>3</span><div><p class="eyebrow">DELIVERY</p><h2>Which deliveries are late?</h2></div></div>${late.length?late.slice(0,3).map(s=>`<button class="analytics-row" data-trace="${s.batchId}"><b>${med(s.medicineId).name}</b><span>${s.delay} days late · ${s.eta}</span><span>${s.destination}</span></button>`).join(''):'<p>No delayed deliveries in these demo records.</p>'}<button class="btn quiet" data-page="shipments">Track deliveries →</button></section></div><p class="analytics-footnote">Stock estimates use usable quantity and average daily use. This is operational demo information, not clinical guidance.</p>`}
function settingsPage(){return `${header('Settings','Preferences apply to this demo view. Risk thresholds and weights recalculate the demo assessments.')}<div class="settings-grid"><section class="card"><p class="eyebrow">ORGANIZATION · DEMO</p><h2>Risk Radar model</h2><p>Set relative weights. Total must equal 100%.</p><div class="settings-fields">${Object.entries(state.weights).map(([k,v])=>`<label>${({stockout:'Stockout risk',shipment:'Shipment delay',supplier:'Supplier reliability',expiry:'Expiry exposure',movement:'Unusual movement'})[k]} <input class="control weight-input" type="number" min="0" max="100" data-key="${k}" value="${v}" aria-label="${k} weight percent"><span>%</span></label>`).join('')}</div><div class="weight-total" id="weight-total">Total: ${Object.values(state.weights).reduce((a,b)=>a+b,0)}%</div><div class="settings-fields threshold-fields">${Object.entries(state.thresholds).map(([k,v])=>`<label>${k[0].toUpperCase()+k.slice(1)} classification starts at <input class="control threshold-input" type="number" min="1" max="100" data-key="${k}" value="${v}" aria-label="${k} risk threshold"></label>`).join('')}</div><p class="form-hint">Thresholds must ascend and fit within 0–100.</p>${button('Save risk model','save-risk','primary')}</section><section class="card"><p class="eyebrow">YOUR PREFERENCES</p><h2>Readability & display</h2><label class="setting-row"><span><b>Text size</b><small>Increase text size throughout the workspace.</small></span><button class="btn secondary" data-action="text-size">${state.font}px · change</button></label><label class="setting-row"><span><b>High contrast</b><small>Strengthen text and interface contrast.</small></span><input type="checkbox" data-pref="contrast" ${state.contrast?'checked':''} aria-label="Enable high contrast"></label><label class="setting-row"><span><b>Reduced motion</b><small>Limit transitions and animated movement.</small></span><input type="checkbox" data-pref="motion" ${state.reduced?'checked':''} aria-label="Enable reduced motion"></label></section><section class="card"><p class="eyebrow">ORGANIZATION · DEMO</p><h2>Inventory thresholds</h2><p>Low stock is flagged at or below medicine-specific stock cover thresholds. Near expiry defaults to 30 days. Sample data only.</p><div class="callout"><div><b>Expiry warning window</b><p>30 days · Applied to all demo batches</p></div></div></section><section class="card"><p class="eyebrow">NOTIFICATIONS · PERSONAL</p><h2>Notification preferences</h2><p>In-app reminders are simulated. SMS and WhatsApp are not connected in this demo.</p><label class="setting-row"><span><b>In-app reminders</b><small>Show refill planning reminders in this demo.</small></span><input id="pref-inapp" type="checkbox" ${state.notificationPreferences.inApp?'checked':''} aria-label="In-app reminders"></label><label class="setting-row"><span><b>SMS and WhatsApp</b><small>Not connected in demo.</small></span><span class="badge neutral">Not connected</span></label></section></div>`}
function homePage(){if(state.role==='Caregiver'&&!state.plan.caregiverConsent)return `${header('Your medicines','Shared medicine details appear only with the patient’s permission.')}<div class="callout"><div class="callout-icon">i</div><div><b>No refill details are shared</b><p>The patient has not enabled caregiver updates for this demo plan.</p></div></div>${button('Find a medicine','go-scan','primary')}`;const next=med(state.plan.medicineId),r=riskFor(next.id);return `${header('Your medicines','Check a medicine or plan a refill.')}<section class="patient-next"><div class="medicine-symbol">↻</div><div><p class="eyebrow">YOUR NEXT REFILL · DEMO</p><h2>${next.name}</h2><p>About ${r.stockout} days of demo stock left · ${state.plan.status}</p><small>Authorized demo quantity: ${state.plan.quantity} ${next.unit}. Your prescription is not changed.</small></div>${button('Review refill','go-refill','primary',`data-med="${next.id}"`)}</section><section class="card patient-list"><div class="section-heading"><div><p class="eyebrow">YOUR MEDICINES</p><h2>Medicine list</h2></div>${button('Scan a medicine','go-scan','secondary')}</div>${[med('med-ins'),med('med-amox')].map(m=>`<div class="medicine-tile"><div class="medicine-symbol">✚</div><div><b>${m.name}</b><p>${m.category}</p></div>${button('Details','scan-med','quiet',`data-med-name="${m.generic}"`)}</div>`).join('')}<p class="consent-note">Demo information only. This app does not check whether a dose was taken. Caregiver updates appear only if you opt in.</p></section>`}
function medicinesPage(){return `${header('Medicines','Your demo medicine list and estimated stock cover.')}<div class="patient-grid">${[med('med-ins'),med('med-amox'),med('med-para')].map(m=>{const r=riskFor(m.id);return `<article class="card patient-med-card"><div class="medicine-symbol">✚</div>${riskBadge(r)}<h2>${m.name}</h2><p>${m.category} · ${m.generic}</p><div class="refill-estimate">About <b>${r.stockout} days</b> of stock left</div><p>Estimate uses demo inventory and average daily use. It is not a dose instruction.</p>${button('Start refill review','go-refill','primary',`data-med="${m.id}"`)}</article>`}).join('')}</div>`}
function refillPage(){let plan=state.plan;const m=med(plan.medicineId)||med('med-ins'),r=riskFor(m.id),early=r.stockout<=7,approval=early||plan.quantity>30;return `${header('Refill plans','Optional planning based on your demo supply records. You stay in control.')}<div class="refill-steps"><span class="${state.refillStep>=1?'current':''}">1 · Review medicine</span><i></i><span class="${state.refillStep>=2?'current':''}">2 · Plan details</span><i></i><span class="${state.refillStep>=3?'current':''}">3 · Confirm</span></div><div class="refill-layout"><section class="card refill-form"><p class="eyebrow">STEP ${state.refillStep} OF 3</p>${state.refillStep===1?`<h2>Choose a medicine</h2><p>Select a regular medicine to review. The plan will not change your dose or authorized quantity.</p><label>Medicine<select id="refill-med" class="control">${['med-ins','med-amox','med-para'].map(id=>`<option value="${id}" ${plan.medicineId===id?'selected':''}>${med(id).name}</option>`).join('')}</select></label>${button('Continue to plan details','refill-next','primary')}`:state.refillStep===2?`<h2>Set your refill preferences</h2><p>Use only the authorized demo quantity. A professional must review early or adjusted refill requests.</p><div class="form-grid"><label>Authorized refill quantity<input id="refill-qty" class="control" type="number" value="${plan.quantity}" min="1" max="30" aria-describedby="qty-hint"><small id="qty-hint">Demo authorized maximum: 30 ${m.unit}. This does not change a prescription.</small></label><label>Preferred delivery day<select id="refill-day" class="control">${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map(x=>`<option ${plan.day===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Delivery preference<select id="refill-delivery" class="control"><option ${plan.delivery==='Home delivery'?'selected':''}>Home delivery</option><option ${plan.delivery==='Local pharmacy pickup'?'selected':''}>Local pharmacy pickup</option></select></label><label>Reminder preference<select id="refill-reminder" class="control"><option value="yes" ${plan.reminder?'selected':''}>In-app reminder</option><option value="no" ${!plan.reminder?'selected':''}>No reminder</option></select></label></div><label class="consent-check"><input id="care-consent" type="checkbox" ${plan.caregiverConsent?'checked':''}><span><b>Allow caregiver reminder updates</b><small>Share refill status with ${esc(plan.caregiverName)}. You can change consent any time.</small></span></label><div class="button-row">${button('Back','refill-back','quiet')}${button('Review before confirming','refill-review','primary')}</div>`:`<h2>Review your refill plan</h2><p>Check each detail. Confirming creates a demo plan only.</p><div class="review-list"><div><span>Medicine</span><b>${m.name}</b></div><div><span>Authorized quantity</span><b>${plan.quantity} ${m.unit} · demo cap 30</b></div><div><span>Preferred day</span><b>${plan.day}</b></div><div><span>Delivery</span><b>${plan.delivery}</b></div><div><span>Estimated stock remaining</span><b>About ${r.stockout} days at sample use</b></div><div><span>Estimated arrival</span><b>Next ${plan.day}, pending approval</b></div></div>${early?`<div class="callout warning"><b>Professional approval needed</b><p>Supply risk suggests preparing earlier. This request remains pending and does not place an order.</p></div>`:`<div class="callout"><b>Demo confirmation only</b><p>No real order is placed and no medicine is dispatched.</p></div>`}<label class="consent-check"><input id="care-consent" type="checkbox" ${plan.caregiverConsent?'checked':''}><span><b>Caregiver reminder consent</b><small>${esc(plan.caregiverName)} may see refill status only because you opted in.</small></span></label><div class="button-row">${button('Back to details','refill-back','quiet')}${button('Confirm demo plan','confirm-refill','primary')}</div>`}</section><aside class="card refill-side"><p class="eyebrow">SUPPLY ESTIMATE · DEMO DATA</p><h2>${m.name}</h2><div class="estimate-number">${r.stockout}<small>days of stock</small></div><p>About ${r.stockout} days of stock at current demo consumption. This estimate can change with inventory and deliveries.</p>${riskBadge(r)}${early?`<div class="side-warning">${r.action}</div>`:''}<div class="consent-note"><b>Safety note</b><p>Medisync demo does not change medicine, dose, or prescribed quantity. Any early refill or substitution requires an authorized professional.</p></div></aside></div><section class="card existing-plan"><div><p class="eyebrow">CURRENT PLAN STATUS</p><h2>${med(state.plan.medicineId).name} · ${state.plan.status}</h2><p>Optional plan · ${state.plan.quantity} units · ${state.plan.day} · ${state.plan.delivery}</p></div>${badge(state.plan.status,state.plan.status==='Awaiting approval'?'moderate':'good')}</section>`}
function remindersPage(){if(state.role==='Caregiver'&&!state.plan.caregiverConsent)return `${header('Reminders','Shared reminders appear only with the patient’s permission.')}<div class="callout"><div class="callout-icon">i</div><div><b>No reminders are shared</b><p>The patient has not opted in to caregiver reminders.</p></div></div>`;return `${header('Reminders','Choose how refill reminders appear. No dose-taking activity is monitored.')}<section class="card reminder-card"><div class="medicine-symbol">◷</div><div><p class="eyebrow">IN-APP · DEMO</p><h2>Refill plan reminder</h2><p>${med(state.plan.medicineId).name} · about ${riskFor(state.plan.medicineId).stockout} days of sample stock remain.</p><span class="quiet-text">${state.plan.reminder?'Reminder preference is on':'Reminder preference is off'} · ${state.plan.caregiverConsent?`Caregiver opted in: ${state.plan.caregiverName}`:'Caregiver updates are off'}</span></div>${button('Review plan','go-refill','secondary')}</section><div class="patient-grid"><section class="card"><h2>Available reminder options</h2><p>In-app reminders are simulated in this demo. SMS and WhatsApp are not connected, and no real message will be sent.</p>${badge('SMS · Not connected in demo','neutral')} ${badge('WhatsApp · Not connected in demo','neutral')}</section><section class="card"><h2>Voice input</h2><p>Try: “Order my regular medicines.” Microphone permission will be requested only after you tap the control. You can always type instead.</p><div class="voice-row"><input id="voice-text" class="control" placeholder="Type a refill request" aria-label="Type a refill request"><button class="btn secondary" data-action="voice">🎙 Start voice input</button></div><p id="voice-help" class="form-hint" aria-live="polite">Typing works in every browser. Voice request needs review and confirmation.</p></section></div>`}
function scanPage(){const m=med(state.scanResult),r=m&&riskFor(m.id),bs=m&&d.batches.filter(b=>b.medicineId===m.id),ship=m&&d.shipments.filter(s=>s.medicineId===m.id&&s.status!=='Delivered'),patient=activeRole()==='patient',plan=m?.id===state.plan.medicineId?state.plan:null,caregiverBlocked=state.role==='Caregiver'&&!state.plan.caregiverConsent;return `${header('Find a medicine','Scan a barcode or type its name to see clear, role-specific details.')}<section class="scanner-layout"><div class="scanner-main card"><div class="scanner-title"><div class="scanner-symbol">▧</div><div><p class="eyebrow">MEDISYNC DEMO LOOKUP</p><h2>Scan or search</h2></div></div><p>Use your camera, enter a demo barcode, or type a medicine name.</p><form id="scan-form" class="scan-form"><label class="sr-only" for="scan-query">Medicine name or barcode</label><input id="scan-query" class="control" value="${esc(state.scanQuery||'')}" placeholder="Example: Amoxicillin or 8901000002502" autocomplete="off"><button class="btn primary" type="submit">Find medicine</button></form><div class="scanner-actions"><button class="btn secondary" data-action="camera">${state.cameraStream?'Stop camera':'Use camera'}</button><span>Camera access is requested only after you choose this button.</span></div>${state.cameraStream?'<video id="camera-video" class="camera-video" playsinline muted aria-label="Camera view for barcode scanning"></video>':''}${state.scanMessage?`<p class="scan-message" role="status">${esc(state.scanMessage)}</p>${!state.scanResult?`<p class="scan-recovery">Try a medicine name or choose one: ${d.medicines.slice(0,3).map(x=>`<button class="table-link" data-code="${d.medicines.find(m=>m.id===x.id)&&Object.keys(d.demoBarcodes).find(c=>d.demoBarcodes[c]===x.id)}">${x.name}</button>`).join(' · ')}. Demo barcodes are printed on sample packages.</p>`:''}`:''}<details class="demo-code-list"><summary>Try a demo barcode</summary><div>${Object.entries(d.demoBarcodes).map(([code,id])=>`<button class="demo-code" data-code="${code}">${med(id).name}<small>${code}</small></button>`).join('')}</div></details>${state.recentScans.length?`<div class="recent-scans"><b>Recently viewed</b>${state.recentScans.map(id=>`<button class="recent-scan" data-code="${Object.keys(d.demoBarcodes).find(c=>d.demoBarcodes[c]===id)}">${med(id).name}<span>View again</span></button>`).join('')}</div>`:''}</div><aside class="scanner-side"><div class="scanner-side-icon">✚</div><h2>Clear details, for your role</h2><p>Patients see their demo refill plan. Operations teams see stock, batches, and deliveries.</p><small>Demo data only · no live barcode database is connected</small></aside></section>${m?`<section class="scan-result"><div class="scan-result-head"><div class="medicine-symbol">✚</div><div><p class="eyebrow">MEDICINE FOUND · DEMO RECORD</p><h2>${m.name}</h2><p>${m.generic} · ${m.category}</p></div>${patient?'':riskBadge(r)}</div><div class="use-explainer"><b>What it is commonly used for</b><p>${d.medicineUses[m.id]}</p><small>This is general information, not personal medical advice. Take medicine only as prescribed or directed by a qualified professional.</small></div>${patient?`<div class="scan-role-details"><div><p class="eyebrow">YOUR DEMO PLAN</p>${caregiverBlocked?'<b>Refill details are not shared with you.</b><p>The patient has not given caregiver permission for this plan.</p>':plan?`<b>${plan.quantity} ${m.unit} authorized in this demo plan</b><p>${plan.status} · preferred ${plan.day} · ${plan.delivery}</p>${state.role==='Caregiver'?`<p>${plan.caregiverConsent?'Patient has opted in to caregiver refill updates.':'Caregiver updates are not enabled by the patient.'}</p>`:''}`:'<b>No personal refill plan is set for this medicine.</b><p>Network stock is not your personal balance.</p>'}</div><div><p class="eyebrow">NEXT STEP</p><p>Need a refill? Review your plan. Your medicine, dose, and prescribed amount will not be changed.</p>${button('Review refill plan','go-refill','primary')}</div></div>`:`<div class="scan-role-details"><div><p class="eyebrow">CURRENT DEMO STOCK</p><b>${r.total.toLocaleString()} ${m.unit} · about ${r.stockout} days at current use</b><p>Average use: ${m.daily} ${m.unit} per day · overall stock cover ${r.pct}%</p><p>Risk score ${r.score} · ${r.level} · ${r.action}</p><p class="plain-why"><b>Why this status?</b> ${r.stockout<=7?`At the current use of ${m.daily} ${m.unit} per day, usable stock is estimated to last about ${r.stockout} days.`:`Current stock and expected use indicate about ${r.stockout} days before restocking is needed.`} ${r.inbound.length?`The next recorded delivery is ${r.inbound[0].delay?`${r.inbound[0].delay} days late`:'on schedule'} and is due ${r.inbound[0].eta}.`:'No delivery is expected before the stock estimate runs out.'}${stockGap(m,r)}</p></div><div><p class="eyebrow">BATCHES & LOCATIONS</p>${bs.map(b=>`<p><button class="table-link" data-trace="${b.id}">${b.id}</button> · ${b.quantity.toLocaleString()} ${m.unit} · ${location(b.locationId)} · expires ${b.expiry}</p>`).join('')}</div></div><div class="scan-supply-list"><p class="eyebrow">INCOMING / SUPPLIED TO</p>${ship.length?ship.map(s=>`<p><b>${s.id}</b> · ${s.quantity.toLocaleString()} ${m.unit} to ${s.destination} · ${s.status}${s.delay?` · ${s.delay} days late`:''} · ETA ${s.eta}</p>`).join(''):'<p>No incoming shipment in these demo records.</p>'}<p>Demo suppliers: ${[...new Set(bs.map(b=>supplier(b.supplierId)?.name))].join(', ')}.</p></div><div class="button-row">${button('Find backup supplier','finder','secondary',`data-med="${m.id}"`)}${button('View risk explanation','open-risk','quiet',`data-id="${m.id}"`)}</div>`}</section>`:''}`}
function pageView(){if(activeRole()==='patient'){return ({home:homePage,scan:scanPage,medicines:medicinesPage,refill:refillPage,reminders:remindersPage}[state.page]||homePage)()}return ({dashboard,scan:scanPage,inventory:inventoryPage,risks:risksPage,shipments:shipmentsPage,trace:tracePage,suppliers:suppliersPage,alerts:alertsPage,analytics:analyticsPage,settings:settingsPage}[state.page]||dashboard)()}
function modalView(){if(state.modal==='finder')return finderModal();if(state.modal==='risk')return riskModal();if(state.modal==='supplier'){const s=supplier(state.selected);return `<div class="modal-backdrop" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close" data-action="close-modal" aria-label="Close dialog">×</button><p class="eyebrow">SUPPLIER PROFILE · DEMO DATA</p><h2 id="modal-title">${s.name}</h2><p>${s.location} · ${s.distance} km from Riverside General Hospital</p><div class="review-list"><div><span>Status</span><b>${s.status}</b></div><div><span>Reliability</span><b>${s.reliability}%</b></div><div><span>Demo stock</span><b>${s.units.toLocaleString()} units</b></div><div><span>Average delivery</span><b>${s.delivery} days</b></div><div><span>Medicines supplied</span><b>${s.medicines.join(', ')}</b></div><div><span>Delayed shipments</span><b>${s.delayed}</b></div></div><p class="form-hint">Sample supplier record. No live supplier connection is available.</p>${button('Close','close-modal','primary')}</section></div>`}if(state.modal==='method')return `<div class="modal-backdrop" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close" data-action="close-modal" aria-label="Close dialog">×</button><p class="eyebrow">TRANSPARENT DEMO MODEL</p><h2 id="modal-title">How this risk score is calculated</h2><p>Each factor is normalized to 0–100. Its displayed contribution is factor score × factor weight. The weighted contributions are added and rounded to classify the medicine.</p><div class="model-list">${Object.entries(state.weights).map(([k,v])=>`<div><span>${({stockout:'Stockout risk',shipment:'Shipment delay',supplier:'Supplier reliability',expiry:'Expiry exposure',movement:'Unusual inventory movement'})[k]}</span><b>${v}%</b></div>`).join('')}</div><p>Stockout is estimated from usable quantity ÷ average daily consumption. Incoming quantities count only if expected before stockout. Expiry exposure estimates the portion of near-expiry stock not expected to be consumed. Movement risk appears only for an explicitly recorded demo anomaly.</p><div class="class-legend">Low 0–29 · Moderate ${state.thresholds.moderate}–${state.thresholds.high-1} · High ${state.thresholds.high}–${state.thresholds.critical-1} · Critical ${state.thresholds.critical}–100</div>${button('Close','close-modal','primary')}</section></div>`;return ''}
function riskModal(){const r=riskFor(state.selected);return `<div class="modal-backdrop" data-action="close-modal"><section class="modal wide-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close" data-action="close-modal" aria-label="Close dialog">×</button><p class="eyebrow">RISK ASSESSMENT · DEMO DATA</p><h2 id="modal-title">${r.medicine.name}</h2><div class="risk-modal-hero">${riskBadge(r)}<b>${r.score}<small> / 100</small></b><span>Estimated stockout: ${r.stockout} days · ${r.pct}% stock cover</span></div><div class="risk-modal-grid"><div><h3>What is driving the score?</h3>${r.factors.map(f=>`<div class="factor"><span>${f.label}</span><span>${f.detail}</span><b>+${f.contribution}</b></div>`).join('')}</div><div><h3>Recommended next step</h3><p>${r.action}</p><h3>Incoming supply</h3>${r.inbound.map(s=>`<p>${s.id}: ${s.quantity} units, ETA ${s.eta}${s.delay?`, delayed ${s.delay} days`:''}.</p>`).join('')||'<p>No incoming shipment counted before estimated stockout.</p>'}<h3>Batch and expiry</h3>${r.batches.map(b=>`<p>${b.id} · ${b.quantity} units · expires ${b.expiry}</p>`).join('')}</div></div><div class="button-row">${button('Find alternative suppliers','finder','primary',`data-med="${r.medicineId}"`)}${button('Open inventory','modal-inventory','secondary',`data-med="${r.medicineId}"`)}</div></section></div>`}
function finderModal(){const medId=state.selected||'med-amox',m=med(medId),req=state.supplierReq,matches=state.finderMatches?.medicineId===medId?state.finderMatches.results:supplierMatches(m.name,req);return `<div class="modal-backdrop" data-action="close-modal"><section class="modal wide-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close" data-action="close-modal" aria-label="Close dialog">×</button><p class="eyebrow">SUPPLIER DECISION WORKFLOW · DEMO</p><h2 id="modal-title">Find alternative suppliers</h2><p>Automatic match for <b>${m.name}</b>. Matches are based on your requirements and demo supplier records. This does not place an order or contact a supplier.</p><div class="requirement-row"><label>Required quantity<input class="control req-input" data-key="quantity" type="number" min="1" value="${req.quantity}"></label><label>Delivery within (days)<input class="control req-input" data-key="days" type="number" min="1" value="${req.days}"></label><label>Maximum distance (km)<input class="control req-input" data-key="distance" type="number" min="1" value="${req.distance}"></label><label>Minimum reliability (%)<input class="control req-input" data-key="reliability" type="number" min="0" max="100" value="${req.reliability}"></label></div><div class="supplier-results">${matches.map(s=>`<article class="supplier-match ${s.eligible?'eligible':''}"><div class="match-top"><div><b>${s.short} · ${s.name}</b><small>${s.distance} km away · ${s.location}</small></div>${badge(s.classification,s.eligible?'good':s.passes.length?'moderate':'neutral')}</div><div class="match-stats"><span>${s.units.toLocaleString()} units</span><span>${s.delivery} day${s.delivery===1?'':'s'}</span><span>${s.reliability}% reliability</span><span>${s.status}</span></div><div class="match-reasons"><div><b>Meets</b><span>${s.passes.length?s.passes.join(' · '):'—'}</span></div><div><b>Needs attention</b><span>${s.reasons.length?s.reasons.join(' · '):'All requirements met'}</span></div></div><button class="btn ${state.flagged.includes(s.id)?'flagged':'secondary'}" data-flag="${s.id}" ${s.eligible?'':'title="You can still flag for follow-up; requirements are not fully met."'}>${state.flagged.includes(s.id)?'✓ Flagged for follow-up':'Flag for follow-up'}</button></article>`).join('')}</div><div class="modal-footnote">Supplier A: 12 km · 1,200 units · 1 day. Supplier B: 38 km · 4,000 units · 3 days. Supplier C: 18 km · 800 units · 2 days. Default rules also require ≥${req.reliability}% reliability and active supplier status.</div></section></div>`}
function render(){document.body.classList.toggle('high-contrast',state.contrast);document.body.classList.toggle('reduced-motion',state.reduced);document.documentElement.style.setProperty('--base-font',`${state.font}px`);app.innerHTML=state.roleScreen?access():shell();}
function stopCamera(){if(state.cameraStream){state.cameraStream.getTracks().forEach(track=>track.stop());state.cameraStream=null}}
function lookupMedicine(value){stopCamera();const v=value.trim().toLowerCase(),id=d.demoBarcodes[value.trim()]||d.medicines.find(m=>m.name.toLowerCase().includes(v)||m.generic.toLowerCase().includes(v))?.id;if(id){state.scanResult=id;state.recentScans=[id,...state.recentScans.filter(x=>x!==id)].slice(0,4);state.scanMessage=`${med(id).name} found.`}else{state.scanResult=null;state.scanMessage='No demo medicine matched. Check the barcode or try a medicine name.'}render()}
function go(page){stopCamera();document.body.classList.remove('nav-open');state.page=page;state.modal=null;state.query='';state.filter='All';render();window.scrollTo(0,0)}
function toast(msg){state.notice=msg;render();setTimeout(()=>{if(state.notice===msg){state.notice='';render()}},3200)}
function saveWeights(){const vals=[...document.querySelectorAll('.weight-input')],sum=vals.reduce((a,e)=>a+(+e.value||0),0);const th=Object.fromEntries([...document.querySelectorAll('.threshold-input')].map(e=>[e.dataset.key,+e.value]));if(sum!==100){toast(`Risk weights add to ${sum}%; adjust them to total 100%.`);return}if(!(th.moderate>=1&&th.moderate<th.high&&th.high<th.critical&&th.critical<=100)){toast('Thresholds must ascend from 1 to 100.');return}state.weights=Object.fromEntries(vals.map(e=>[e.dataset.key,+e.value]));state.thresholds=th;service.updateSettings({weights:state.weights,thresholds:state.thresholds}).then(()=>toast('Risk model saved locally; scores and alerts recalculated.')).catch(error=>toast(`Could not save settings: ${error.message}`));}
async function exportCsv(){const rows=[['Medicine','Generic name','Batch','Quantity','Unit','Stock cover %','Days remaining','Expiry','Supplier','Location','Risk score','Risk class']];d.batches.forEach(b=>{const m=med(b.medicineId),r=riskFor(m.id);rows.push([m.name,m.generic,b.id,b.quantity,m.unit,r.pct,Math.ceil(b.quantity/m.daily),b.expiry,supplier(b.supplierId)?.name,location(b.locationId),r.score,r.level])});const csv='Demo data — sample records\n'+rows.map(row=>row.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='medisync-demo-inventory.csv';a.click();URL.revokeObjectURL(a.href);toast('Sample CSV downloaded.');}
app.addEventListener('input',e=>{if(e.target.id==='scan-query')state.scanQuery=e.target.value;if(e.target.id==='search'){state.query=e.target.value;const pos=e.target.selectionStart;render();const x=document.querySelector('#search');x.focus();x.setSelectionRange(pos,pos)}if(e.target.matches('.req-input')){state.supplierReq[e.target.dataset.key]=+e.target.value||0;const focusKey=e.target.dataset.key;render();document.querySelector(`.req-input[data-key="${focusKey}"]`)?.focus();refreshSupplierMatches(focusKey)}if(e.target.matches('.weight-input')){const total=[...document.querySelectorAll('.weight-input')].reduce((a,x)=>a+(+x.value||0),0);document.querySelector('#weight-total').textContent=`Total: ${total}%`}});
app.addEventListener('submit',e=>{if(e.target.id==='scan-form'){e.preventDefault();lookupMedicine(document.querySelector('#scan-query').value)}});
app.addEventListener('change',e=>{if(e.target.id==='filter'){state.filter=e.target.value;render()}if(e.target.id==='alert-filter'){state.filter=e.target.value;render()}if(e.target.id==='trace-batch'){state.selected=e.target.value;render()}if(e.target.matches('.req-input'))refreshSupplierMatches();if(e.target.id==='pref-inapp'){state.notificationPreferences.inApp=e.target.checked;service.updateNotificationPreferences({inApp:e.target.checked}).then(()=>toast('Notification preference saved.')).catch(error=>toast(`Could not save preference: ${error.message}`));}if(e.target.matches('[data-pref="contrast"]')){state.contrast=e.target.checked;render()}if(e.target.matches('[data-pref="motion"]')){state.reduced=e.target.checked;render()}if(e.target.id==='refill-med'){state.plan.medicineId=e.target.value;render()}if(e.target.id==='care-consent')state.plan.caregiverConsent=e.target.checked});
app.addEventListener('click',async e=>{const t=e.target.closest('button,[data-page]');if(!t)return;if(t.dataset.page){document.body.classList.remove('nav-open');go(t.dataset.page);return}if(t.dataset.openMed){state.selected=t.dataset.openMed;state.modal='risk';render();return}if(t.dataset.openRisk){state.selected=t.dataset.openRisk;state.modal='risk';render();return}if(t.dataset.trace){stopCamera();state.selected=t.dataset.trace;state.page='trace';state.modal=null;render();return}if(t.dataset.supplier){state.selected=t.dataset.supplier;state.modal='supplier';render();return}if(t.dataset.alertDetail){const a=alertList().find(x=>x.id===t.dataset.alertDetail);state.selected=a?.medicineId;state.modal='risk';render();return}if(t.dataset.assignAlert){state.alertOwners[t.dataset.assignAlert]=state.role;state.notice=`Alert assigned to ${state.role}.`;render();return}if(t.dataset.action){const a=t.dataset.action;if(a==='enter'){state.role=document.querySelector('#role-choice').value;state.page=activeRole()==='patient'?'home':'dashboard';state.roleScreen=false;render();window.scrollTo(0,0)}else if(a==='role-switch'){stopCamera();state.notice='';state.roleScreen=true;render()}else if(a==='dismiss-toast'){state.notice='';render()}else if(a==='undo-alert'){if(state.lastAlertChange){const change=state.lastAlertChange;try{await service.updateAlert(change.id,change.previous);state.alerts[change.id]=change.previous;state.lastAlertChange=null;state.notice='Alert change undone.';}catch(error){state.notice=`Could not undo alert update: ${error.message}`;}render()}}else if(a==='text-size'){state.font=state.font>=22?18:state.font+2;render()}else if(a==='contrast'){state.contrast=!state.contrast;render()}else if(a==='motion'){state.reduced=!state.reduced;render()}else if(a==='menu'){document.body.classList.toggle('nav-open')}else if(a==='finder'){state.selected=t.dataset.med||state.selected||'med-amox';state.finderMatches=null;state.modal='finder';render();refreshSupplierMatches()}else if(a==='risk-method'){state.modal='method';render()}else if(a==='close-modal'){state.modal=null;render()}else if(a==='open-risk'){state.selected=t.dataset.id;state.modal='risk';render()}else if(a==='modal-inventory'){state.modal=null;state.page='inventory';state.role='Inventory Manager';state.roleScreen=false;render()}else if(a==='clear-filters'){state.filter='All';state.query='';render()}else if(a==='export'){exportCsv()}else if(a==='save-risk'){saveWeights()}else if(a==='assign-alert'){try{await service.updateAlertOwner(t.dataset.id,state.role);state.alertOwners[t.dataset.id]=state.role;state.notice=`Alert assigned to ${state.role}.`;}catch(error){state.notice=`Could not save assignment: ${error.message}`;}render()}else if(a==='ack'||a==='resolve'){const previous=alertList().find(x=>x.id===t.dataset.id)?.status||'Open',next=a==='ack'?'Acknowledged':'Resolved';try{await service.updateAlert(t.dataset.id,next);state.lastAlertChange={id:t.dataset.id,previous};state.alerts[t.dataset.id]=next;state.notice=`Alert ${a==='ack'?'acknowledged':'resolved'}.`;}catch(error){state.notice=`Could not update alert: ${error.message}`;}render()}else if(a==='go-refill'){if(t.dataset.med)state.plan.medicineId=t.dataset.med;go('refill')}else if(a==='go-scan'){go('scan')}else if(a==='scan-med'){state.scanQuery=t.dataset.medName||'';state.scanResult=null;go('scan');lookupMedicine(state.scanQuery)}else if(a==='camera'){if(state.cameraStream){stopCamera();state.scanMessage='Camera stopped.';render()}else if(!navigator.mediaDevices?.getUserMedia){state.scanMessage='Camera access is unavailable here. Type a medicine name or demo barcode instead.';render()}else if(!('BarcodeDetector' in window)){state.scanMessage='This browser cannot read barcodes from the camera. Type the medicine name or demo barcode instead.';render()}else{try{state.cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});state.scanMessage='Camera ready. Hold a demo barcode steady in view.';render();const video=document.querySelector('#camera-video');video.srcObject=state.cameraStream;await video.play();const detector=new BarcodeDetector();const scan=async()=>{if(!state.cameraStream||!video.isConnected)return;try{const found=await detector.detect(video);if(found.length){stopCamera();lookupMedicine(found[0].rawValue);return}}catch{}requestAnimationFrame(scan)};requestAnimationFrame(scan)}catch{state.cameraStream=null;state.scanMessage='Camera permission was declined or unavailable. Type the barcode or medicine name instead.';render()}}}else if(a==='refill-next'){state.refillStep=2;render()}else if(a==='refill-back'){state.refillStep=Math.max(1,state.refillStep-1);render()}else if(a==='refill-review'){const qty=Math.max(1,+document.querySelector('#refill-qty').value||1);if(qty>30){toast('Quantity exceeds the demo authorized maximum of 30.');return}state.plan.quantity=qty;state.plan.day=document.querySelector('#refill-day').value;state.plan.delivery=document.querySelector('#refill-delivery').value;state.plan.reminder=document.querySelector('#refill-reminder').value==='yes';state.plan.caregiverConsent=!!document.querySelector('#care-consent')?.checked;state.refillStep=3;render()}else if(a==='confirm-refill'){const r=riskFor(state.plan.medicineId);try{state.plan=await service.createRefillPlan({...state.plan,approvalRequired:r.stockout<=7});state.refillStep=1;state.notice=state.plan.status==='Awaiting approval'?'Plan saved; professional approval is required. No order was placed.':'Demo refill plan confirmed. No order was placed.';state.page='refill';}catch(error){state.notice=`Could not save the demo plan: ${error.message}`;}render()}else if(a==='voice'){const out=document.querySelector('#voice-help');const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){out.textContent='Voice input is not supported here. Type your request above; it works just as well.';return}out.textContent='Your browser will ask for microphone access. Nothing is recorded until you confirm the request.';const recognition=new Speech();recognition.lang='en-IN';recognition.onresult=ev=>{document.querySelector('#voice-text').value=ev.results[0][0].transcript;out.textContent='Request prepared for review. Review and confirm before any demo plan is created.'};recognition.onerror=()=>{out.textContent='Microphone unavailable or permission denied. Type your request above instead.'};recognition.start()}return}if(t.dataset.code){lookupMedicine(t.dataset.code);return}if(t.dataset.flag){const id=t.dataset.flag,flagged=!state.flagged.includes(id);try{const rows=await service.setSupplierFollowUp(id,state.selected,flagged);state.flagged=rows.map(x=>x.supplierId);}catch(error){state.notice=`Could not save supplier follow-up: ${error.message}`;}render();return}});
app.addEventListener('click',e=>{if(e.target.dataset.action==='close-modal'&&e.target.classList.contains('modal-backdrop')){state.modal=null;render()}});
async function start(){try{const boot=await service.bootstrap();Object.assign(d,boot.data);state.weights={...boot.state.weights};state.thresholds={...boot.state.thresholds};state.alerts={...boot.state.alertStatuses};state.alertOwners={...boot.state.alertOwners};state.plan={...(boot.state.refillPlans?.[0]||d.patientPlan)};state.flagged=(boot.state.supplierFollowUps||[]).map(x=>x.supplierId);state.notificationPreferences={...boot.state.preferences};state.apiConnected=true;}catch(error){state.apiConnected=false;state.apiError=error.message;state.notice='Local demo service could not be reached. Start Medisync using its setup guide.';}render();}
start();
